logical_plan:
Sink
  Project [service, window_start, p99]
    Aggregate group_by=[service] aggs=[P99(value)]
      Window Tumble { size_ns: 1000000000 }
        Filter Binary { left: Column("name"), op: Like, right: Literal(Text("%latency%")) }
          Scan metrics [*]

optimized_logical_plan:
Sink
  Aggregate group_by=[service] aggs=[P99(value)]
    Window Tumble { size_ns: 1000000000 }
      Filter Binary { left: Column("name"), op: Like, right: Literal(Text("%latency%")) }
        Scan metrics [service, name, value, event_time]
